import {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {UpOutlined} from "@ant-design/icons";
import {loadContentAsync} from "../../state/book-reducer";
import VsnSloka from "./vsn-sloka";

export default function Svsn() {
  const [vsnContent, setVsnContent] = useState(null);
  const [show, setShow] = useState({
    poorvangam: false,
    poorvanyasaha: false,
    dhyaanam: false,
    mahamantram: true,
    phalasruti: false,
  });
  let content = useSelector(state => state.vsnContent)
  let dispatch = useDispatch()

  useEffect(() => {
    dispatch(loadContentAsync())
  }, []);

  useEffect(() => {
    setVsnContent(content)
  }, [content])

  if (!vsnContent || vsnContent?.slokas["maha-mantram"]?.length === 0) {
    return null
  }

  const renderTitle = (title, showProp, align) => {
    return <div className={"text-white text-xl pl-5 " + (align || "text-left")}
                onClick={() => setShow({...show, ...showProp})}>
      <div className="p-2"></div>
      {title}
    </div>
  }

  const renderCollapseIcon = (section) => {
    return <UpOutlined
      className="text-palegoldenrod"
      onClick={() => setShow({...show, ...section})}
    />
  }

  return (
    <>
      {renderTitle("పూర్వాఙ్గమ్", {poorvangam: !show.poorvangam})}
      {show.poorvangam && (
        <>
          {[...Array(108)].map((_, index) => (
            <VsnSloka
              key={index}
              sloka={vsnContent?.slokas?.poorvangam?.[index + 1]}
              num={index + 1}
            />
          ))}
          {renderCollapseIcon({poorvangam: false})}
        </>
      )}

      {renderTitle("పూర్వన్యాసః", {poorvanyasaha: !show.poorvanyasaha})}
      {show.poorvanyasaha && <>
        <VsnSloka sloka={vsnContent?.slokas?.["poorvanyasaha"]}/>
        {renderCollapseIcon({poorvanyasaha: false})}
      </>}

      {renderTitle("ధ్యానం", {dhyaanam: !show.dhyaanam})}
        {show.dhyaanam && [...Array(108)].map((item, index) =>
          <VsnSloka sloka={vsnContent?.slokas?.["dhyaanam"]?.[index + 1]} num={index + 1}
                    key={index}/>
        )}
      {show.dhyaanam && renderCollapseIcon({dhyaanam: false})}

        {renderTitle(vsnContent?.slokas?.["maha-mantram"]?.["start-line"], {mahamantram: !show.mahamantram})}
        {show.mahamantram && [...Array(108)].map((item, index) =>
          <VsnSloka sloka={vsnContent?.slokas?.["maha-mantram"]?.[index + 1]} num={index + 1}
                    slokaMeaning={vsnContent?.slokasMeaning?.slokam?.[`s${index + 1}`]}
                    key={index}/>
        )}
        {show.mahamantram && renderCollapseIcon({mahamantram: false})}

        {renderTitle("ఫలశ్రుతిః", {phalasruti: !show.phalasruti})}
        {show.phalasruti && [...Array(108)].map((item, index) =>
          <VsnSloka sloka={vsnContent?.slokas?.["phalasruti"]?.[index + 1]} num={index + 1}
                    key={index}/>
        )}
        {show.phalasruti && renderCollapseIcon({phalasruti: false})}
    </>
  )
}
